// Posters and validation are generated by default; pass --video to also export MP4.
import fs from 'node:fs/promises';import path from 'node:path';import {fileURLToPath,pathToFileURL} from 'node:url';import {spawn} from 'node:child_process';import {once} from 'node:events';import assert from 'node:assert/strict';import sharp from 'sharp';
const dir=path.dirname(fileURLToPath(import.meta.url)),bundle=path.resolve(process.argv[2]),temp=path.join(dir,'temp/shape-chapter'),out=path.resolve(dir,'../IMAGE/07-SW-Shape');await fs.mkdir(temp,{recursive:true});
const trace=JSON.parse(await fs.readFile(path.join(dir,'shape-engine-trace.txt'),'utf8')),variant=JSON.parse(await fs.readFile(path.join(dir,'shape-engine-variant.txt'),'utf8'));const cases=Object.fromEntries(trace.cases.map(c=>[c.name,c]));const lua=v=>Array.isArray(v)?'{'+v.map(lua).join(',')+'}':v&&typeof v==='object'?'{'+Object.entries(v).map(([k,v])=>`${k}=${lua(v)}`).join(',')+'}':JSON.stringify(v);
const {createTMath}=await import(pathToFileURL(path.join(bundle,'client.js')));const runtime=await createTMath('return tmath.scene{theme="pro_white"}','init.lua',{renderEngine:'cpu',wasmBinary:await fs.readFile(path.join(bundle,'tmath-wasm.wasm'))});runtime.font('Pretendard',await fs.readFile(path.join(bundle,'Pretendard.ttf')));
const names=JSON.parse(await fs.readFile(path.join(dir,'shape-scenes.txt'),'utf8'));const reports=[];
try{for(const name of names){if(process.argv.includes('--only')&&name!==process.argv[process.argv.indexOf('--only')+1])continue;const source=await fs.readFile(path.join(dir,'sw-shape-'+name+'.lua'),'utf8');assert(source.includes('local trace='+lua(trace)));runtime.loadLua(source,name+'.lua');const [width,height]=runtime.size(),duration=runtime.duration,frames=Math.ceil(duration*30)+1;let margin=Infinity,checks=0;const labels=new Set();
for(let f=0;f<frames;f++){const objs=runtime.layoutReport(Math.min(f/30,duration),4).objects,texts=[];for(const o of objs){if(o.type==='text')assert(o.id?.startsWith('label_'));if(!o.visible||o.type==='group')continue;const b=o.paintBounds;if(!b)continue;const m=Math.min(b.x,b.y,width-b.x-b.width,height-b.y-b.height);margin=Math.min(margin,m);assert(m>=4,`${name} overflow ${o.id} ${m}`);if(o.type==='text'){labels.add(o.id);texts.push(o);}}for(let i=0;i<texts.length;i++)for(let j=i+1;j<texts.length;j++){const a=texts[i].paintBounds,b=texts[j].paintBounds;assert(Math.max(a.x-b.x-b.width,b.x-a.x-a.width)>=4||Math.max(a.y-b.y-b.height,b.y-a.y-a.height)>=4,`${name} text gap ${texts[i].id}/${texts[j].id}`);}}
const samples=[0,duration/2,duration];const checkGrid=(time,c,bx,by,u)=>{const b=Buffer.from(runtime.render(time,true));for(let y=0;y<trace.h;y++)for(let x=0;x<trace.w;x++){const at=(Math.floor(by+(y+.5)*u)*width+Math.floor(bx+(x+.5)*u))*4,p=c.pixels[y*trace.stride+x],rgb=[p&255,(p>>>8)&255,(p>>>16)&255];assert(rgb.every((v,j)=>Math.abs(v-b[at+j])<=1),`${name} ${c.name} pixel ${x},${y} time ${time}`);checks++;}};
if(name==='01-path-storage'){for(let i=1;i<=5;i++){const b=runtime.bounds('copy_dot_'+i,duration);assert(Math.abs(b.x+b.width/2-1430)<1);assert(Math.abs(b.y+b.height/2-(240+(i-1)*110))<1);checks++;}}
if(name==='02-bezier'){const lerp=(a,b,t)=>a.map((v,i)=>v+(b[i]-v)*t);for(let k=0;k<=60;k++){const t=k/60,c=trace.bezier.control,a=[lerp(c[0],c[1],t),lerp(c[1],c[2],t),lerp(c[2],c[3],t)],b=[lerp(a[0],a[1],t),lerp(a[1],a[2],t)],p=lerp(b[0],b[1],t);assert(p.every((v,i)=>Math.abs(v-trace.bezier.samples[k][i])<.0001));checks++;}}
if(name==='03-bounds'){for(const [id,b,bx]of[['tight',cases.fill.tight,100],['hull',cases.fill.controlBox,100],['device_hull',cases.bounds.controlBox,1050],['render_box',cases.bounds.renderBox,1050]]){const r=runtime.bounds(id,duration);assert(Math.abs(r.x-(bx+b[0]*28))<2&&Math.abs(r.width-(b[2]-b[0])*28)<3);checks++;}}
if(name==='04-path-rle'){let t=.8+cases.fill.rle.length*.045+.8;for(let y=0;y<trace.h;y++){t+=.03+.12+.03;const expected={...cases.fill,pixels:cases.fill.pixels.map((v,i)=>Math.floor(i/trace.stride)<=y?v:trace.background)};checkGrid(t+.001,expected,1350,290,18);}checkGrid(duration,cases.fill,1350,290,18);}
if(name==='05-stroke'){let t=.5;for(const [i,key]of['cap0','cap2','cap1','join0','join1','join2'].entries()){t+=(i?.2:0)+.6+(i===0?.8:0)+.6+.7;checkGrid(t+.5,cases[key],1050,250,28);samples.push(t+.5);t+=1.4;}}
if(name==='06-dash'){let t=.7;for(let i=0;i<=5;i++){t+=(i?.18:0)+.5+.5+.5;checkGrid(t+.4,cases['dash'+i],1050,250,28);samples.push(t+.4);t+=1;}}
if(name==='07-trim'){let t=.7;for(let i=1;i<=4;i++){t+=(i>1?.2:0)+.6+.6+.35+.35;checkGrid(t+.5,cases['trim1_'+i],100,570,22);checkGrid(t+.5,cases['trim0_'+i],1050,570,22);samples.push(t+.5);t+=1.3;}}
const canonical=Buffer.from(runtime.render(duration,true));runtime.loadLua(source.replace('local trace='+lua(trace),'local trace='+lua(variant)),name+'-variant.lua');const varied=Buffer.from(runtime.render(runtime.duration,true));let differences=0;for(let i=0;i<canonical.length;i++)if(canonical[i]!==varied[i])differences++;assert(differences>0,name+' variant did not affect render');
const vcases=Object.fromEntries(variant.cases.map(c=>[c.name,c]));if(name==='04-path-rle')checkGrid(runtime.duration,vcases.fill,1350,290,18);if(name==='05-stroke')checkGrid(runtime.duration,vcases.join2,1050,250,28);if(name==='06-dash')checkGrid(runtime.duration,vcases.dash5,1050,250,28);if(name==='07-trim'){checkGrid(runtime.duration,vcases.trim1_4,100,570,22);checkGrid(runtime.duration,vcases.trim0_4,1050,570,22);}
runtime.loadLua(source,name+'.lua');const report={name,width,height,duration,frames,labels:labels.size,minMargin:margin,checks,variantChangedChannels:differences};reports.push(report);console.log(JSON.stringify(report));
for(const [i,time]of samples.entries())await sharp(Buffer.from(runtime.render(time,true)),{raw:{width,height,channels:4}}).png().toFile(path.join(temp,name+'-'+i+'.png'));
await sharp(Buffer.from(runtime.render(duration,true)),{raw:{width,height,channels:4}}).webp({lossless:true}).toFile(path.join(out,name+'.webp'));
if(!process.argv.includes('--preview') && process.argv.includes('--video')){const ff=spawn('ffmpeg',['-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','rgba','-video_size',`${width}x${height}`,'-framerate','30','-i','pipe:0','-an','-c:v','libx264','-preset','medium','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',path.join(out,name+'.mp4')],{stdio:['pipe','inherit','inherit']});const end=once(ff,'close');for(let f=0;f<frames;f++)if(!ff.stdin.write(Buffer.from(runtime.render(Math.min(f/30,duration),true))))await once(ff.stdin,'drain');ff.stdin.end();const [code]=await end;assert.equal(code,0);}
await fs.writeFile(path.join(temp,'review.txt'),JSON.stringify(reports,null,2)+'\nNo inline raster review; earlier thread budget exhausted.\n');
}}finally{runtime.destroy();}
